              : Value(serieFiscal),
      folioFiscal:
          folioFiscal == null && nullToAbsent
              ? const Value.absent()
              : Value(folioFiscal),
      fechaTimbrado: Value(fechaTimbrado),
      montoTotal: Value(montoTotal),
      estatus: Value(estatus),
